#!/usr/bin/env python3
"""Generates gameplay/runner/gait_model.gd from tools/gait_reference.py (tables are injected so Python and GDScript cannot drift)."""
import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parent))
import gait_reference as g
from assetgen import human_rig as rig

TEMPLATE = r'''extends RefCounted
class_name GaitModel
## Biomechanical running gait and whole body poses of the NEXALANE runner (0.5.0).
##
## GENERATED by tools/gen_gait_model.py from tools/gait_reference.py (the executable specification) - edit the Python
## reference and regenerate, do not edit the tables here.  tests/qa_harness.gd compares golden values with the Python output.
##
## Everything here is a pure function of its arguments (no nodes, no engine state), so it is unit-testable and can drive a
## player runner and ghost runners alike.  Angles are RADIANS, lengths METRES.
##
## Conventions (see tools/assetgen/human_rig.py): the runner faces +Z, its left side is +X, every bone has an identity rest
## rotation.  Channel angles are anatomical (flexion positive) except the trunk / head channels, which are raw rotations about
## +X (pitch, forward lean positive), +Y (yaw, turn left positive) and +Z (roll, tip right positive).

const DEG: float = PI / 180.0
const GRAVITY: float = 9.81

# ---- channel layout -----------------------------------------------------------------------------------------------
const PEL_X: int = 0
const PEL_Z: int = 1
const PEL_PITCH: int = 2
const PEL_YAW: int = 3
const PEL_ROLL: int = 4
const SPN_PITCH: int = 5
const SPN_YAW: int = 6
const SPN_ROLL: int = 7
const CHS_PITCH: int = 8
const CHS_YAW: int = 9
const CHS_ROLL: int = 10
const NCK_PITCH: int = 11
const NCK_YAW: int = 12
const NCK_ROLL: int = 13
const HD_PITCH: int = 14
const HD_YAW: int = 15
const HD_ROLL: int = 16
const ARM: int = 17          # + side * 8 + A_*
const A_CLAV_YAW: int = 0
const A_CLAV_ELEV: int = 1
const A_SH_FLEX: int = 2
const A_SH_ABD: int = 3
const A_SH_ROT: int = 4
const A_ELBOW: int = 5
const A_FORE_ROT: int = 6
const A_WRIST: int = 7
const LEG: int = 33          # + side * 6 + L_*
const L_HIP_FLEX: int = 0
const L_HIP_ABD: int = 1
const L_HIP_ROT: int = 2
const L_KNEE: int = 3
const L_ANKLE: int = 4
const L_TOE: int = 5
const N_CH: int = 45

# ---- skeleton dimensions (mirror tools/assetgen/human_rig.py) -----------------------------------------------------
const THIGH: float = %(THIGH)s
const SHANK: float = %(SHANK)s
const HIP_HALF_WIDTH: float = %(HIPW)s
const HIP_DROP: float = %(HIPDROP)s
const ANKLE_HEIGHT: float = %(ANKLE)s
const TOE_Z: float = %(TOEZ)s
const TOE_Y: float = %(TOEY)s
const HEEL_Z: float = %(HEELZ)s
const TOE_TIP_Z: float = %(TIPZ)s
const REST_HIPS_Y: float = %(HIPSY)s

# ---- tables: 20 keys per gait cycle (phase 0 = left foot initial contact), degrees ----------------------------------
# thigh = ABSOLUTE forward angle from vertical (hip flexion = thigh + pelvis tilt), knee = flexion, foot = absolute pitch (toes down +)
const THIGH_JOG: Array = %(THIGH_JOG)s
const THIGH_SPR: Array = %(THIGH_SPR)s
const KNEE_JOG: Array = %(KNEE_JOG)s
const KNEE_SPR: Array = %(KNEE_SPR)s
const FOOT_JOG: Array = %(FOOT_JOG)s
const FOOT_SPR: Array = %(FOOT_SPR)s
const STANCE_JOG: float = %(STANCE_JOG)s
const STANCE_SPR: float = %(STANCE_SPR)s

const SLIDE_PELVIS_Y: float = %(SLIDE_Y)s
const AIR_PELVIS_Y: float = %(AIR_Y)s
const READY_KNEE_BACK_DEG: float = %(READY_KNEE)s


static func arm_ch(side: int, k: int) -> int:
	return ARM + side * 8 + k


static func leg_ch(side: int, k: int) -> int:
	return LEG + side * 6 + k


static func new_pose() -> PackedFloat32Array:
	var c := PackedFloat32Array()
	c.resize(N_CH)
	return c


## Periodic uniform Catmull-Rom sample of a table (phase in cycles).
static func cyc(table: Array, ph: float) -> float:
	var n: int = table.size()
	var x: float = (ph - floorf(ph)) * float(n)
	var i: int = int(floorf(x))
	var f: float = x - float(i)
	var p0: float = float(table[(i - 1 + n) %% n])
	var p1: float = float(table[i %% n])
	var p2: float = float(table[(i + 1) %% n])
	var p3: float = float(table[(i + 2) %% n])
	return 0.5 * ((2.0 * p1) + (-p0 + p2) * f + (2.0 * p0 - 5.0 * p1 + 4.0 * p2 - p3) * f * f + (-p0 + 3.0 * p1 - 3.0 * p2 + p3) * f * f * f)


# ---- speed -> gait parameters -------------------------------------------------------------------------------------
## 0 = relaxed jog, 1 = full sprint.  Game speeds (16..31 m/s) are far beyond a human, so the legs run at 'flat out' effort
## over the whole range and only cadence / lean keep growing.
static func intensity(speed: float) -> float:
	if speed <= 0.0:
		return 0.0
	if speed < 8.0:
		return 0.40 * speed / 8.0
	return clampf(0.40 + 0.60 * (speed - 8.0) / 16.0, 0.0, 1.0)


static func overdrive(speed: float) -> float:
	return clampf((speed - 24.0) / 10.0, 0.0, 1.0)


## Gait cycles per second (two steps per cycle).
static func cadence(u: float, over: float) -> float:
	return 1.25 + 1.10 * u + 0.20 * over


static func stance_fraction(u: float) -> float:
	return lerpf(STANCE_JOG, STANCE_SPR, u)


# ---- the running pose ---------------------------------------------------------------------------------------------
## ph = phase of the LEFT leg in cycles; extra_lean (rad) = acceleration lean; launch 0..1 = standing-start drive;
## turn = signed lane change input (-1..1, + = left).
static func run_pose(ph: float, u: float, over: float, extra_lean: float, launch: float, turn: float) -> PackedFloat32Array:
	var c: PackedFloat32Array = new_pose()
	var s_frac: float = stance_fraction(u)
	var sw: float = TAU
	var tilt: float = (3.0 + 4.0 * u) * DEG + 0.45 * extra_lean + 1.8 * DEG * sin(2.0 * sw * (ph - 0.10))
	c[PEL_PITCH] = tilt
	c[PEL_ROLL] = lerpf(2.5, 5.0, u) * DEG * sin(sw * ph)
	c[PEL_YAW] = lerpf(4.0, 8.0, u) * DEG * sin(sw * ph)
	c[PEL_X] = lerpf(0.012, 0.018, u) * sin(sw * ph)
	var lean: float = (4.0 + 9.0 * u + 3.0 * over) * DEG + extra_lean + launch * 16.0 * DEG
	var rest_lean: float = lean - tilt
	c[SPN_PITCH] = 0.40 * rest_lean
	c[CHS_PITCH] = 0.60 * rest_lean
	var twist: float = (lerpf(4.0, 8.0, u) + lerpf(5.0, 9.0, u)) * DEG
	c[SPN_YAW] = -0.40 * twist * sin(sw * ph)
	c[CHS_YAW] = -0.60 * twist * sin(sw * ph)
	c[SPN_ROLL] = -0.55 * c[PEL_ROLL]
	c[CHS_ROLL] = -0.30 * c[PEL_ROLL]
	c[NCK_PITCH] = -0.40 * 0.75 * lean
	c[HD_PITCH] = -0.60 * 0.75 * lean
	var yaw_sum: float = c[PEL_YAW] + c[SPN_YAW] + c[CHS_YAW]
	var roll_sum: float = c[PEL_ROLL] + c[SPN_ROLL] + c[CHS_ROLL]
	c[NCK_YAW] = -0.45 * yaw_sum + 0.30 * turn * 0.35
	c[HD_YAW] = -0.45 * yaw_sum + 0.70 * turn * 0.35
	c[NCK_ROLL] = -0.40 * roll_sum
	c[HD_ROLL] = -0.40 * roll_sum
	var af: float = (25.0 + 30.0 * u + 5.0 * over + 10.0 * launch) * DEG
	var ab: float = (32.0 + 33.0 * u + 5.0 * over + 8.0 * launch) * DEG
	var em: float = (85.0 + 10.0 * u) * DEG
	for side in range(2):
		var q: float = ph + 0.5 * float(side)
		var sn: float = sin(sw * (q - 0.02))
		c[arm_ch(side, A_SH_FLEX)] = 0.5 * (af - ab) + 0.5 * (af + ab) * sn
		c[arm_ch(side, A_ELBOW)] = em + 14.0 * DEG * sn
		c[arm_ch(side, A_SH_ABD)] = (8.0 + 3.0 * sn) * DEG
		c[arm_ch(side, A_FORE_ROT)] = -8.0 * DEG
		c[arm_ch(side, A_WRIST)] = 6.0 * DEG
		c[arm_ch(side, A_CLAV_YAW)] = 2.5 * DEG * sn
		c[arm_ch(side, A_CLAV_ELEV)] = 1.5 * DEG * absf(sn)
	for side in range(2):
		var p: float = ph + 0.5 * float(side)
		var hip: float = lerpf(cyc(THIGH_JOG, p), cyc(THIGH_SPR, p), u) * DEG + tilt
		var knee: float = lerpf(cyc(KNEE_JOG, p), cyc(KNEE_SPR, p), u) * DEG
		var foot: float = lerpf(cyc(FOOT_JOG, p), cyc(FOOT_SPR, p), u) * DEG
		c[leg_ch(side, L_HIP_FLEX)] = hip
		c[leg_ch(side, L_KNEE)] = knee
		c[leg_ch(side, L_ANKLE)] = foot - (tilt - hip + knee)
		c[leg_ch(side, L_HIP_ABD)] = (3.0 + 2.0 * sin(sw * p)) * DEG
		var pf: float = p - floorf(p)
		var w: float = smoothstep(0.0, 0.03, pf) * (1.0 - smoothstep(s_frac, s_frac + 0.04, pf))
		c[leg_ch(side, L_TOE)] = -clampf(foot, 0.0, 40.0 * DEG) * w
	return c


# ---- forward kinematics of the legs (sagittal contact maths) --------------------------------------------------------
static func pelvis_basis(c: PackedFloat32Array) -> Basis:
	return Basis.from_euler(Vector3(c[PEL_PITCH], c[PEL_YAW], c[PEL_ROLL]))


static func thigh_basis(c: PackedFloat32Array, side: int) -> Basis:
	var sgn: float = 1.0 if side == 0 else -1.0
	return Basis.from_euler(Vector3(-c[leg_ch(side, L_HIP_FLEX)], -sgn * c[leg_ch(side, L_HIP_ROT)], sgn * c[leg_ch(side, L_HIP_ABD)]))


## Height (relative to the Hips bone origin) of the lowest point of one foot (heel, ball of foot or toe tip).
static func foot_low(c: PackedFloat32Array, side: int) -> float:
	var sgn: float = 1.0 if side == 0 else -1.0
	var bp: Basis = pelvis_basis(c)
	var hip: Vector3 = bp * Vector3(sgn * HIP_HALF_WIDTH, -HIP_DROP, 0.0)
	var bt: Basis = bp * thigh_basis(c, side)
	var knee: Vector3 = hip + bt * Vector3(0.0, -THIGH, 0.0)
	var bs: Basis = bt * Basis.from_euler(Vector3(c[leg_ch(side, L_KNEE)], 0.0, 0.0))
	var ankle: Vector3 = knee + bs * Vector3(0.0, -SHANK, 0.0)
	var bf: Basis = bs * Basis.from_euler(Vector3(c[leg_ch(side, L_ANKLE)], 0.0, 0.0))
	var heel: Vector3 = ankle + bf * Vector3(0.0, -ANKLE_HEIGHT, HEEL_Z)
	var toe_joint: Vector3 = ankle + bf * Vector3(0.0, TOE_Y - ANKLE_HEIGHT, TOE_Z)
	var ball: Vector3 = toe_joint + bf * Vector3(0.0, -TOE_Y, 0.0)
	var bto: Basis = bf * Basis.from_euler(Vector3(c[leg_ch(side, L_TOE)], 0.0, 0.0))
	var tip: Vector3 = toe_joint + bto * Vector3(0.0, -TOE_Y, TOE_TIP_Z)
	return minf(heel.y, minf(ball.y, tip.y))


## Hips bone height that keeps both feet on / above the ground.
static func support_height(c: PackedFloat32Array) -> float:
	return maxf(-foot_low(c, 0), -foot_low(c, 1))


static func _env(q: float, u: float, over: float, extra_lean: float, launch: float) -> float:
	return support_height(run_pose(q, u, over, extra_lean, launch, 0.0))


## Vertical pelvis path of the run: foot planted during stance, ballistic arc during the two flight phases.
static func run_pelvis_y(ph: float, u: float, over: float, extra_lean: float, launch: float, cad: float) -> float:
	var s_frac: float = stance_fraction(u)
	var p: float = ph - floorf(ph)
	if p < s_frac or (p >= 0.5 and p < 0.5 + s_frac):
		return _env(p, u, over, extra_lean, launch)
	var a: float = 0.5 + s_frac
	var b: float = 1.0
	if p < 0.5:
		a = s_frac
		b = 0.5
	var tau: float = (p - a) / (b - a)
	var ya: float = _env(a, u, over, extra_lean, launch)
	var yb: float = _env(b, u, over, extra_lean, launch)
	var tf: float = (b - a) / maxf(cad, 0.1)
	var amp: float = GRAVITY * tf * tf / 8.0
	var y: float = ya + (yb - ya) * tau + 4.0 * amp * tau * (1.0 - tau)
	return maxf(y, _env(p, u, over, extra_lean, launch))


# ---- other whole body poses ---------------------------------------------------------------------------------------
## Relaxed standing pose with breathing and a slow weight shift (t in seconds).
static func idle_pose(t: float) -> PackedFloat32Array:
	var c: PackedFloat32Array = new_pose()
	var br: float = sin(t * 1.7)
	var sh: float = sin(t * 0.37)
	c[PEL_PITCH] = 3.0 * DEG
	c[PEL_ROLL] = 1.2 * DEG * sh
	c[PEL_YAW] = 1.0 * DEG * sin(t * 0.23)
	c[PEL_X] = 0.010 * sh
	c[SPN_PITCH] = 1.5 * DEG + 0.5 * DEG * br
	c[CHS_PITCH] = 1.0 * DEG + 0.8 * DEG * br
	c[CHS_ROLL] = -1.0 * DEG * sh
	c[NCK_PITCH] = -1.0 * DEG
	c[HD_PITCH] = -2.0 * DEG + 1.0 * DEG * sin(t * 0.5)
	c[HD_YAW] = 6.0 * DEG * sin(t * 0.31) * sin(t * 0.11)
	for side in range(2):
		var q: float = 1.0 if side == 0 else -1.0
		c[arm_ch(side, A_SH_FLEX)] = (4.0 + 1.0 * br) * DEG
		c[arm_ch(side, A_SH_ABD)] = (6.0 + 1.0 * br) * DEG
		c[arm_ch(side, A_ELBOW)] = (16.0 + 2.0 * sin(t * 0.9 + float(side))) * DEG
		c[arm_ch(side, A_FORE_ROT)] = 10.0 * DEG
		c[arm_ch(side, A_WRIST)] = 4.0 * DEG
		c[arm_ch(side, A_CLAV_ELEV)] = 1.0 * DEG * br
		c[leg_ch(side, L_HIP_FLEX)] = (3.0 + q * 0.8 * sh) * DEG
		c[leg_ch(side, L_KNEE)] = (4.0 + q * 0.8 * sh) * DEG
		c[leg_ch(side, L_HIP_ABD)] = 3.0 * DEG
		c[leg_ch(side, L_ANKLE)] = -(c[PEL_PITCH] - c[leg_ch(side, L_HIP_FLEX)] + c[leg_ch(side, L_KNEE)])
	return c


## Sprinter's 'get set' stance used during the countdown: staggered feet, weight forward, arms ready.
static func ready_pose(t: float) -> PackedFloat32Array:
	var c: PackedFloat32Array = new_pose()
	var br: float = sin(t * 2.6)
	c[PEL_PITCH] = 16.0 * DEG
	c[PEL_YAW] = 3.0 * DEG
	c[SPN_PITCH] = 8.0 * DEG + 0.6 * DEG * br
	c[CHS_PITCH] = 10.0 * DEG + 0.8 * DEG * br
	c[CHS_YAW] = -6.0 * DEG
	c[NCK_PITCH] = -12.0 * DEG
	c[HD_PITCH] = -10.0 * DEG
	c[HD_YAW] = 3.0 * DEG
	c[leg_ch(0, L_HIP_FLEX)] = 46.0 * DEG
	c[leg_ch(0, L_KNEE)] = 62.0 * DEG
	c[leg_ch(1, L_HIP_FLEX)] = 6.0 * DEG
	c[leg_ch(1, L_KNEE)] = READY_KNEE_BACK_DEG * DEG
	for side in range(2):
		c[leg_ch(side, L_HIP_ABD)] = 3.0 * DEG
		c[leg_ch(side, L_ANKLE)] = -(c[PEL_PITCH] - c[leg_ch(side, L_HIP_FLEX)] + c[leg_ch(side, L_KNEE)])
	c[arm_ch(1, A_SH_FLEX)] = 42.0 * DEG
	c[arm_ch(1, A_ELBOW)] = 95.0 * DEG
	c[arm_ch(0, A_SH_FLEX)] = -38.0 * DEG
	c[arm_ch(0, A_ELBOW)] = 85.0 * DEG
	for side in range(2):
		c[arm_ch(side, A_SH_ABD)] = 9.0 * DEG
		c[arm_ch(side, A_FORE_ROT)] = -6.0 * DEG
	return c


## Feet-first slide: trunk reclined ~62 deg, legs reaching forward, arms trailing.  Stays below 0.90 m (hit box 0.95 m).
static func slide_pose(lead: int) -> PackedFloat32Array:
	var c: PackedFloat32Array = new_pose()
	c[PEL_PITCH] = -62.0 * DEG
	c[SPN_PITCH] = -6.0 * DEG
	c[CHS_PITCH] = -4.0 * DEG
	c[NCK_PITCH] = 26.0 * DEG
	c[HD_PITCH] = 12.0 * DEG
	for side in range(2):
		var is_lead: bool = side == lead
		var thigh: float = (86.0 if is_lead else 82.0) * DEG
		var knee: float = (2.0 if is_lead else 9.0) * DEG
		var hip: float = thigh + c[PEL_PITCH]
		c[leg_ch(side, L_HIP_FLEX)] = hip
		c[leg_ch(side, L_KNEE)] = knee
		c[leg_ch(side, L_ANKLE)] = -22.0 * DEG - (c[PEL_PITCH] - hip + knee)
		c[leg_ch(side, L_HIP_ABD)] = 5.0 * DEG
		c[arm_ch(side, A_SH_FLEX)] = -50.0 * DEG
		c[arm_ch(side, A_SH_ABD)] = 26.0 * DEG
		c[arm_ch(side, A_ELBOW)] = 24.0 * DEG
		c[arm_ch(side, A_WRIST)] = -12.0 * DEG
	return c


## Hurdle style leap.  a = 0..1 progress through the flight, lead = side of the leading leg.
static func air_pose(a: float, lead: int) -> PackedFloat32Array:
	var c: PackedFloat32Array = new_pose()
	var take: float = 1.0 - smoothstep(0.0, 0.22, a)
	var land: float = smoothstep(0.58, 0.92, a)
	var mid: float = maxf(1.0 - take - land, 0.0)
	c[PEL_PITCH] = (10.0 * take + 14.0 * mid + 6.0 * land) * DEG
	c[SPN_PITCH] = (6.0 * take + 10.0 * mid + 2.0 * land) * DEG
	c[CHS_PITCH] = (6.0 * take + 12.0 * mid + 2.0 * land) * DEG
	c[NCK_PITCH] = -12.0 * DEG
	c[HD_PITCH] = -10.0 * DEG
	for side in range(2):
		var is_lead: bool = side == lead
		var hip: float
		var knee: float
		var foot: float
		var shoulder: float
		if is_lead:
			hip = -8.0 * take + 72.0 * mid + 38.0 * land + 60.0 * take
			knee = 12.0 * take + 38.0 * mid + 22.0 * land + 70.0 * take
			foot = 34.0 * take - 4.0 * mid + 22.0 * land
			shoulder = 20.0 * take - 10.0 * mid + 30.0 * land
		else:
			hip = -14.0 * take + 14.0 * mid + 22.0 * land
			knee = 24.0 * take + 112.0 * mid + 50.0 * land
			foot = 34.0 * take + 18.0 * mid + 22.0 * land
			shoulder = 62.0 * take + 48.0 * mid + 30.0 * land
		c[leg_ch(side, L_HIP_FLEX)] = hip * DEG
		c[leg_ch(side, L_KNEE)] = knee * DEG
		c[leg_ch(side, L_ANKLE)] = foot * DEG - (c[PEL_PITCH] - hip * DEG + knee * DEG)
		c[leg_ch(side, L_HIP_ABD)] = (4.0 + 6.0 * mid) * DEG
		c[arm_ch(side, A_SH_FLEX)] = shoulder * DEG
		c[arm_ch(side, A_SH_ABD)] = (14.0 + 22.0 * mid) * DEG
		c[arm_ch(side, A_ELBOW)] = (80.0 * take + 70.0 * mid + 60.0 * land) * DEG
	return c


## Impact absorption: deep hip / knee / ankle flexion, trunk folded forward, arms thrown forward.
static func land_pose() -> PackedFloat32Array:
	var c: PackedFloat32Array = new_pose()
	c[PEL_PITCH] = 26.0 * DEG
	c[SPN_PITCH] = 10.0 * DEG
	c[CHS_PITCH] = 10.0 * DEG
	c[NCK_PITCH] = -18.0 * DEG
	c[HD_PITCH] = -14.0 * DEG
	for side in range(2):
		var hip: float = 58.0 * DEG
		var knee: float = 78.0 * DEG
		c[leg_ch(side, L_HIP_FLEX)] = hip
		c[leg_ch(side, L_KNEE)] = knee
		c[leg_ch(side, L_ANKLE)] = -(c[PEL_PITCH] - hip + knee)
		c[leg_ch(side, L_HIP_ABD)] = 7.0 * DEG
		c[arm_ch(side, A_SH_FLEX)] = 36.0 * DEG
		c[arm_ch(side, A_SH_ABD)] = 22.0 * DEG
		c[arm_ch(side, A_ELBOW)] = 62.0 * DEG
	return c


## The instant of impact: upper body snaps back, arms fly out, legs brace.
static func hit_recoil_pose() -> PackedFloat32Array:
	var c: PackedFloat32Array = new_pose()
	c[PEL_PITCH] = 4.0 * DEG
	c[SPN_PITCH] = -8.0 * DEG
	c[CHS_PITCH] = -10.0 * DEG
	c[NCK_PITCH] = 12.0 * DEG
	c[HD_PITCH] = 10.0 * DEG
	for side in range(2):
		var hip: float = 24.0 * DEG
		var knee: float = 34.0 * DEG
		c[leg_ch(side, L_HIP_FLEX)] = hip
		c[leg_ch(side, L_KNEE)] = knee
		c[leg_ch(side, L_ANKLE)] = -(c[PEL_PITCH] - hip + knee)
		c[leg_ch(side, L_HIP_ABD)] = 10.0 * DEG
		c[arm_ch(side, A_SH_FLEX)] = 78.0 * DEG
		c[arm_ch(side, A_SH_ABD)] = 52.0 * DEG
		c[arm_ch(side, A_ELBOW)] = 34.0 * DEG
		c[arm_ch(side, A_WRIST)] = -20.0 * DEG
	return c


## Winded crouch after the stumble: knees bent, trunk folded, head down, hands towards the knees.
static func hit_down_pose() -> PackedFloat32Array:
	var c: PackedFloat32Array = new_pose()
	c[PEL_PITCH] = 34.0 * DEG
	c[SPN_PITCH] = 22.0 * DEG
	c[CHS_PITCH] = 20.0 * DEG
	c[NCK_PITCH] = -6.0 * DEG
	c[HD_PITCH] = 18.0 * DEG
	for side in range(2):
		var hip: float = 78.0 * DEG
		var knee: float = 96.0 * DEG
		c[leg_ch(side, L_HIP_FLEX)] = hip
		c[leg_ch(side, L_KNEE)] = knee
		c[leg_ch(side, L_ANKLE)] = -(c[PEL_PITCH] - hip + knee)
		c[leg_ch(side, L_HIP_ABD)] = 12.0 * DEG
		c[arm_ch(side, A_SH_FLEX)] = 40.0 * DEG
		c[arm_ch(side, A_SH_ABD)] = 14.0 * DEG
		c[arm_ch(side, A_ELBOW)] = 34.0 * DEG
	return c


## Linear blend of two channel sets; returns the blended set (use the return value: `pose = GaitModel.blend_into(pose, other, w)`).
static func blend_into(into: PackedFloat32Array, other: PackedFloat32Array, w: float) -> PackedFloat32Array:
	if w <= 0.0001:
		return into
	for i in range(N_CH):
		into[i] = lerpf(into[i], other[i], w)
	return into
'''

def fmt(arr):
    return '[' + ', '.join(f'{float(v):.1f}' for v in arr) + ']'

ready = g.ready_pose(0.0)
vals = dict(
    THIGH=f'{rig.THIGH:.3f}', SHANK=f'{rig.SHANK:.3f}', HIPW=f'{rig.HIP_HALF_WIDTH:.3f}', HIPDROP=f'{rig.HIP_DROP:.3f}',
    ANKLE=f'{rig.ANKLE_HEIGHT:.3f}', TOEZ=f'{rig.TOE_JOINT[0]:.3f}', TOEY=f'{rig.TOE_JOINT[1]:.3f}', HEELZ=f'{rig.HEEL_Z:.3f}',
    TIPZ=f'{rig.TOE_TIP_Z:.3f}', HIPSY=f'{rig.BONES[0][2][1]:.3f}',
    THIGH_JOG=fmt(g.THIGH_JOG), THIGH_SPR=fmt(g.THIGH_SPR), KNEE_JOG=fmt(g.KNEE_JOG), KNEE_SPR=fmt(g.KNEE_SPR),
    FOOT_JOG=fmt(g.FOOT_JOG), FOOT_SPR=fmt(g.FOOT_SPR), STANCE_JOG=f'{g.STANCE_JOG:.2f}', STANCE_SPR=f'{g.STANCE_SPR:.2f}',
    SLIDE_Y=f'{g.SLIDE_PELVIS_Y:.3f}', AIR_Y=f'{g.AIR_PELVIS_Y:.3f}',
    READY_KNEE=f'{ready[g.leg_ch(1, g.L_KNEE)] / g.D:.3f}',
)
out = Path(__file__).resolve().parent.parent / 'gameplay' / 'runner' / 'gait_model.gd'
out.write_text(TEMPLATE % vals)
print('wrote', out, len(TEMPLATE % vals), 'bytes')
